@SpringBootTest @ActiveProfiles("integration-test")
class WorkoutMutationIT{
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired ExerciseEntryV2Service creates;@Autowired WorkoutEstimateService estimates;@Autowired WorkoutMutationService mutations;@Autowired WorkoutCorrectionPreviewService previews;@Autowired WorkoutSnapshotReader snapshots;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired JdbcTemplate jdbc;@Autowired ExerciseRecordService oldWrites;@Autowired SubmissionService receipts;
 User owner;WorkoutV2TestFixtures.Catalogue catalogue;LocalDate date=LocalDate.of(2020,1,2);long id;UUID submission;
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);catalogue=WorkoutV2TestFixtures.catalogue(jdbc);var input=new WorkoutPreview(UUID.randomUUID(),"Original workout",List.of(new PreviewPeriod(UUID.randomUUID(),"STRENGTH",Long.toString(catalogue.strengthOption()),new BigDecimal("50"),Map.of(),List.of(new Movement(catalogue.movements().getFirst().toString(),3L,8L,new BigDecimal("40")))),new PreviewPeriod(UUID.randomUUID(),"ACTIVITY",Long.toString(catalogue.cardioOption()),new BigDecimal("20"),Map.of(),List.of())),null);var preview=estimates.previewNew(owner.getId(),new PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,input));var ps=new ArrayList<Period>();for(int i=0;i<2;i++){var p=input.periods().get(i);ps.add(new Period(p.clientEntryId(),p.periodKind(),p.optionId(),p.durationMinutes(),p.equipmentDetails(),p.movements(),preview.periods().get(i).calculationFingerprint()));}submission=UUID.randomUUID();id=Long.parseLong(creates.createEntryV2(owner.getId(),new CreateRequest(submission,date,"Australia/Sydney",RecordSource.MANUAL,preview.fingerprint(),new Workout(input.clientEntryId(),input.title(),ps,null))).roots().getFirst().id());}
 Workout original(){return (Workout)snapshots.detailForReuse(owner.getId(),"workout",id).input();}
 UpdateRequest reviewed(Workout entry,LocalDate day,long version){var response=previews.previewOwnedRoot(owner.getId(),"workout",id,new CorrectionRequest(version,day,"Australia/Sydney",entry));return new UpdateRequest(version,day,"Australia/Sydney",entry,response.fingerprint());}
 Period changed(Period p,String minutes,List<Movement>moves){return new Period(p.clientEntryId(),p.periodKind(),p.optionId(),new BigDecimal(minutes),p.equipmentDetails(),moves,p.calculationFingerprint());}
 @Test void detailOnlyChangesRetainStoredEnergyDespiteWeightAndInactiveOriginal(){var before=original();jdbc.update("UPDATE exercise_record SET estimated_kj=123.456 WHERE user_id=? AND period_kind='STRENGTH'",owner.getId());jdbc.update("UPDATE weight_entry SET weight_kg=80 WHERE user_id=?",owner.getId());jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.strengthOption());jdbc.update("UPDATE movement_catalogue SET active=false WHERE id=?",catalogue.movements().getFirst());var p=before.periods().getFirst();var incoming=new Workout(before.clientEntryId(),"Renamed",List.of(changed(p,"50",List.of(new Movement(catalogue.movements().getFirst().toString(),4L,null,new BigDecimal("60")))),before.periods().get(1)),null);var result=mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed(incoming,date,0));assertEquals(1,result.version());assertEquals(new BigDecimal("611.589"),result.preview().knownEnergyKj());assertEquals(new BigDecimal("123.456"),jdbc.queryForObject("SELECT estimated_kj FROM exercise_record WHERE user_id=? AND period_kind='STRENGTH'",BigDecimal.class,owner.getId()));assertEquals(new BigDecimal("70.00"),jdbc.queryForObject("SELECT weight_kg_used FROM exercise_record WHERE user_id=? AND period_kind='STRENGTH'",BigDecimal.class,owner.getId()));assertEquals(4,jdbc.queryForObject("SELECT set_count FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=?",Integer.class,owner.getId()));assertEquals(1,mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed((Workout)result.input(),date,1)).version());assertEquals("VERSION_CONFLICT",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"workout",id,new UpdateRequest(0L,date,"Australia/Sydney",incoming,null))).code());}
 @Test void titleOnlyPreservesEveryUnchangedPeriodRowAndMovement(){
  var old=original();var rows=jdbc.queryForList("SELECT * FROM exercise_record WHERE user_id=? ORDER BY id",owner.getId());var movements=jdbc.queryForList("SELECT m.* FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=? ORDER BY m.id",owner.getId());
  var changed=new Workout(old.clientEntryId(),"Only the parent title changed",old.periods(),old.originWorkoutId());
  var result=mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed(changed,date,0));
  assertEquals(1,result.version());assertEquals("Only the parent title changed",((Workout)result.input()).title());
  assertEquals(rows,jdbc.queryForList("SELECT * FROM exercise_record WHERE user_id=? ORDER BY id",owner.getId()),"Title-only correction must not rewrite period snapshots, timestamps or versions");
  assertEquals(movements,jdbc.queryForList("SELECT m.* FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=? ORDER BY m.id",owner.getId()));
  assertEquals(0,receipts.findReceiptV2(owner.getId(),submission).roots().getFirst().versionAtCreation());
 }
 @Test void changedDateOrMinutesRecalculatesOnlyRelatedPeriods(){var old=original();jdbc.update("UPDATE exercise_record SET estimated_kj=123.456 WHERE user_id=? AND period_kind='STRENGTH'",owner.getId());var incoming=new Workout(old.clientEntryId(),old.title(),List.of(old.periods().getFirst(),changed(old.periods().get(1),"30",List.of())),null);var result=mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed(incoming,date,0));assertEquals(new BigDecimal("855.656"),result.preview().knownEnergyKj());jdbc.update("INSERT INTO weight_entry(user_id,created_at,entry_date,weight_kg) VALUES(?,now(),DATE '2020-01-03',80)",owner.getId());var day=LocalDate.of(2020,1,3);result=mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed((Workout)result.input(),day,1));assertEquals(new BigDecimal("1813.067"),result.preview().knownEnergyKj());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM exercise_record WHERE user_id=? AND recorded_date=? AND weight_kg_used=80",Long.class,owner.getId(),day));}
 @Test void wholeDeletePreservesProofDetailsAndBlocksV1ChildWrites(){long child=jdbc.queryForObject("SELECT min(id) FROM exercise_record WHERE user_id=?",Long.class,owner.getId());assertEquals("GROUP_EDIT_REQUIRED",assertThrows(BusinessException.class,()->oldWrites.softDeleteOwned(owner.getId(),child,0L)).code());var type=jdbc.queryForObject("SELECT exercise_type_id FROM exercise_record WHERE id=?",Long.class,child);assertEquals("GROUP_EDIT_REQUIRED",assertThrows(BusinessException.class,()->oldWrites.updateOwned(owner.getId(),child,new UpdateExerciseRecordRequest(0L,type.toString(),new BigDecimal("50"),date,"Australia/Sydney",null))).code());mutations.softDeleteOwnedRoot(owner.getId(),"workout",id,0L);assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM exercise_record WHERE user_id=? AND deleted_at IS NOT NULL",Long.class,owner.getId()));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=?",Long.class,owner.getId()));assertEquals(1,receipts.findReceiptV2(owner.getId(),submission).roots().size());assertThrows(BusinessException.class,()->snapshots.detailForReuse(owner.getId(),"workout",id));mutations.softDeleteOwnedRoot(owner.getId(),"workout",id,0L);assertEquals("GROUP_EDIT_REQUIRED",assertThrows(BusinessException.class,()->oldWrites.softDeleteOwned(owner.getId(),child,0L)).code());}
 @Test void ownershipUuidAndInactiveNewPeriodCannotBorrowHistoricalException(){var old=original();var foreign=FoodV2TestFixtures.owner(users,profiles);assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->previews.previewOwnedRoot(foreign.getId(),"workout",id,new CorrectionRequest(0L,date,"Australia/Sydney",old))).code());jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.strengthOption());var p=old.periods().getFirst();var fresh=new Period(UUID.randomUUID(),p.periodKind(),p.optionId(),p.durationMinutes(),p.equipmentDetails(),p.movements(),p.calculationFingerprint());var input=new Workout(old.clientEntryId(),old.title(),List.of(old.periods().get(1),fresh),null);assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->previews.previewOwnedRoot(owner.getId(),"workout",id,new CorrectionRequest(0L,date,"Australia/Sydney",input))).code());assertEquals(0,snapshots.detailForReuse(owner.getId(),"workout",id).version());}
 @Test void removeAndAddPeriodsRemainOneAtomicOccurrenceWithReservedRemovedIdentity(){var old=original();var removed=old.periods().getFirst();var fresh=new Period(UUID.randomUUID(),"ACTIVITY",Long.toString(catalogue.unavailableOption()),BigDecimal.TEN,Map.of(),List.of(),"a".repeat(64));var incoming=new Workout(old.clientEntryId(),old.title(),List.of(old.periods().get(1),fresh),null);var result=mutations.updateOwnedRoot(owner.getId(),"workout",id,reviewed(incoming,date,0));assertEquals(1,result.version());assertEquals(new BigDecimal("30.00"),result.preview().totalMinutes());assertTrue(result.preview().partial());assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM exercise_record WHERE user_id=?",Long.class,owner.getId()));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM exercise_record WHERE user_id=? AND client_entry_id=? AND deleted_at IS NOT NULL",Long.class,owner.getId(),removed.clientEntryId()));var restore=new Workout(old.clientEntryId(),old.title(),List.of(old.periods().get(1),removed),null);assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"workout",id,new UpdateRequest(1L,date,"Australia/Sydney",restore,null))).code());}
 @Test void latePeriodUpdateFailureRollsBackParentAndEarlierDetailChanges(){var old=original();var first=changed(old.periods().getFirst(),"50",List.of(new Movement(catalogue.movements().getFirst().toString(),5L,8L,new BigDecimal("60"))));var incoming=new Workout(old.clientEntryId(),"Must roll back",List.of(first,changed(old.periods().get(1),"30",List.of())),null);var input=reviewed(incoming,date,0);String name="fail_mutation_"+UUID.randomUUID().toString().replace("-","");jdbc.execute("CREATE FUNCTION "+name+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.user_id="+owner.getId()+" AND NEW.period_kind='ACTIVITY' AND NEW.duration_minutes=30 THEN RAISE EXCEPTION 'synthetic late correction failure'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER "+name+" BEFORE UPDATE ON exercise_record FOR EACH ROW EXECUTE FUNCTION "+name+"()");try{assertThrows(RuntimeException.class,()->mutations.updateOwnedRoot(owner.getId(),"workout",id,input));assertEquals(0,snapshots.detailForReuse(owner.getId(),"workout",id).version());assertEquals(old,original());assertEquals(3,jdbc.queryForObject("SELECT set_count FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=?",Integer.class,owner.getId()));}finally{jdbc.execute("DROP TRIGGER "+name+" ON exercise_record");jdbc.execute("DROP FUNCTION "+name+"()");}}
 @Test void twoEditorsCannotBothAdvanceTheParentVersion()throws Exception{var old=original();var a=new UpdateRequest(0L,date,"Australia/Sydney",new Workout(old.clientEntryId(),"Editor A",old.periods(),null),null);var b=new UpdateRequest(0L,date,"Australia/Sydney",new Workout(old.clientEntryId(),"Editor B",old.periods(),null),null);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var first=pool.submit(()->{start.await();try{return mutations.updateOwnedRoot(owner.getId(),"workout",id,a).version()==1?"OK":"BAD";}catch(BusinessException e){return e.code();}});var second=pool.submit(()->{start.await();try{return mutations.updateOwnedRoot(owner.getId(),"workout",id,b).version()==1?"OK":"BAD";}catch(BusinessException e){return e.code();}});start.countDown();assertEquals(Set.of("OK","VERSION_CONFLICT"),Set.of(first.get(20,TimeUnit.SECONDS),second.get(20,TimeUnit.SECONDS)));}assertEquals(1,snapshots.detailForReuse(owner.getId(),"workout",id).version());}

 @Test void standaloneQuickUsesOneVersionAndPreservesDetailOnlySnapshot(){UUID uuid=UUID.randomUUID();var input=new QuickPreview(uuid,new PreviewPeriod(uuid,"ACTIVITY",Long.toString(catalogue.cardioOption()),new BigDecimal("20"),Map.of(),List.of()));var authority=estimates.previewNew(owner.getId(),new PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,input));var p=input.period();var entry=new Quick(uuid,new Period(uuid,p.periodKind(),p.optionId(),p.durationMinutes(),Map.of(),List.of(),authority.periods().getFirst().calculationFingerprint()));long quick=Long.parseLong(creates.createEntryV2(owner.getId(),new CreateRequest(UUID.randomUUID(),date,"Australia/Sydney",RecordSource.MANUAL,authority.fingerprint(),entry)).roots().getFirst().id());jdbc.update("UPDATE weight_entry SET weight_kg=80 WHERE user_id=?",owner.getId());var detailed=new Quick(uuid,new Period(uuid,p.periodKind(),p.optionId(),p.durationMinutes(),Map.of("speedKmh",new BigDecimal("5")),List.of(),entry.period().calculationFingerprint()));var result=mutations.updateOwnedRoot(owner.getId(),"quick",quick,new UpdateRequest(0L,date,"Australia/Sydney",detailed,null));assertEquals(1,result.version());assertEquals(new BigDecimal("488.133"),result.preview().knownEnergyKj());assertEquals(1,mutations.updateOwnedRoot(owner.getId(),"quick",quick,new UpdateRequest(1L,date,"Australia/Sydney",detailed,null)).version());var changed=new Quick(uuid,new Period(uuid,p.periodKind(),p.optionId(),new BigDecimal("30"),detailed.period().equipmentDetails(),List.of(),entry.period().calculationFingerprint()));var review=previews.previewOwnedRoot(owner.getId(),"quick",quick,new CorrectionRequest(1L,date,"Australia/Sydney",changed));assertThrows(ExerciseCalculationChangedV2Exception.class,()->mutations.updateOwnedRoot(owner.getId(),"quick",quick,new UpdateRequest(1L,date,"Australia/Sydney",changed,"0".repeat(64))));result=mutations.updateOwnedRoot(owner.getId(),"quick",quick,new UpdateRequest(1L,date,"Australia/Sydney",changed,review.fingerprint()));assertEquals(2,result.version());assertEquals(new BigDecimal("836.800"),result.preview().knownEnergyKj());mutations.softDeleteOwnedRoot(owner.getId(),"quick",quick,2L);assertThrows(BusinessException.class,()->snapshots.detailForReuse(owner.getId(),"quick",quick));}

}
